-- Create "sending_domains" table
CREATE TABLE "public"."sending_domains" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "domain" character varying NOT NULL,
  "dkim_selector" character varying NOT NULL,
  "dkim_private_key_encrypted" character varying NOT NULL,
  "dkim_public_key" character varying NOT NULL,
  "verified" boolean NOT NULL DEFAULT false,
  "last_checked_at" timestamptz NULL,
  "verified_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "sending_domains_workspaces_sending_domains" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "sendingdomain_last_checked_at" to table: "sending_domains"
CREATE INDEX "sendingdomain_last_checked_at" ON "public"."sending_domains" ("last_checked_at");
-- Create index "sendingdomain_workspace_id_domain" to table: "sending_domains"
CREATE UNIQUE INDEX "sendingdomain_workspace_id_domain" ON "public"."sending_domains" ("workspace_id", "domain");
